; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: neogeo (SNK Neo Geo (68000)), starts in turbo mode
; ============================================================

			org 0

NTC_RAMEND	equ $10C000		; the end of the RAM the variables and arrays are in (;@ramend)
NTC_A16ADD	equ $110000		; (;@a16) added to a 16 bit address once sign extended: where the RAM's 64K is (0: $FF8000 on, the Mega Drive)
NTC_A16		macro			; an address register loaded from a 16 bit address (movea.w): to the RAM it means
			ifne NTC_A16ADD
			adda.l #NTC_A16ADD, \1
			endif
			endm
;## ntc_md_vectors ntc_ng_boot
; the cartridge's vectors (the BIOS's routines for the exceptions, as every cartridge has them)
; and the Neo Geo header (the compiler puts this first, at 0)
			dc.l $0010F300				; the supervisor stack
			dc.l $00C00402				; reset: the BIOS
			dc.l $00C00408, $00C0040E, $00C00414, $00C0041A	; bus, address, illegal, zero divide
			dc.l $00C0041A, $00C0041A, $00C0041A, $00C00420	; CHK, TRAPV, privilege, trace
			dc.l $00C00426, $00C00426					; line 1010, 1111
			dcb.l 3, $FFFFFFFF			; 12-14
			dc.l $00C0042C				; 15 uninitialised interrupt
			dcb.l 8, $FFFFFFFF			; 16-23
			dc.l $00C00432				; 24 spurious
			dc.l ntc_ng_vbl				; 25 level 1: VBlank
			dc.l ntc_ng_timer			; 26 level 2: the timer
			dc.l ntc_ng_rte				; 27 level 3
			dcb.l 4, ntc_ng_rte			; 28-31
			dcb.l 32, $FFFFFFFF			; 32-63
; the header ($100): test/ngbuild.js puts in the NGH number and the name
			dc.b "NEO-GEO", 0
			dc.w $0C1C					; $108 the NGH number (3100: not $999, which the emulators take for V-Liner)
			dc.l $00100000				; $10A the program's size
			dc.l $0010E800				; $10E an MVS's backup RAM (none used)
			dc.w 0						; $112 its size
			dc.b 1						; $114 the eye-catcher: the game's (USER request 1, which goes straight back)
			dc.b 0						; $115 its first tile
			dc.l ntc_ng_dip, ntc_ng_dip, ntc_ng_dip	; $116 the soft DIPs: Japan, the US, Europe
			dc.w $4EF9					; $122 USER: jmp abs.l (written out: 6 bytes each, at
			dc.l ntc_ng_user			;      the header's fixed places)
			dc.w $4EF9					; $128 PLAYER_START
			dc.l ntc_ng_rts
			dc.w $4EF9					; $12E DEMO_END
			dc.l ntc_ng_rts
			dc.w $4EF9					; $134 COIN_SOUND
			dc.l ntc_ng_rts
			dcb.b 70, $FF				; $13A
			dc.w 0						; $180
			dc.l ntc_ng_scode			; $182 the security code
ntc_ng_scode:
			dc.w $7600, $4A6D, $0A14, $6600, $003C, $206D, $0A04, $3E2D
			dc.w $0A08, $13C0, $0030, $0001, $3210, $0C01, $00FF, $671A
			dc.w $3028, $0002, $B02D, $0ACE, $6610, $3028, $0004, $B02D
			dc.w $0ACF, $6606, $B22D, $0AD0, $6708, $5088, $51CF, $FFD4
			dc.w $3607, $4E75, $206D, $0A04, $3E2D, $0A08, $3210, $E049
			dc.w $0C01, $00FF, $671A, $3010, $B02D, $0ACE, $6612, $3028
			dc.w $0002, $E048, $B02D, $0ACF, $6606, $B22D, $0AD0, $6708
			dc.w $5888, $51CF, $FFD8, $3607, $4E75
ntc_ng_dip:	dc.b "NTC BASIC       "		; the name the BIOS shows (16)
			dc.b $FF, $FF, $FF, $FF		; no time DIPs
			dc.b $FF, $FF				; no number DIPs
			dcb.b 10, 0					; no choice DIPs
			even

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI, 3 ADM-3A, 4 Televideo (CP/M)
NTC_TERM_RT	equ 0		; 1: the program calls StdIO.SetTerminal (the terminal is chosen while it runs)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_WINPAGED	equ 0		; 1 = page 0 code may sit under the window (Option Memory Paged, not Reserved): the Memory class never hands out page 1 (main RAM's own #4000-#7FFF) when the code reaches past #4000
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_ISLN	equ 1		; interrupt classes (Option Class Interrupt): the slots ntc_isl has (8 bytes each)
NTC_INTS	equ 1		; 0 = the platform never lets interrupts in (;@ints 0: ntc_xn's safe point has no ei)
NTC_PLATRSV	equ 0		; 1 = the platform's fixed areas (;@reserved) are Reserved in the memory map: the build goes round them (the old top-of-RAM asserts are off)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
			rts

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dc.l kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 14: Input "How many numbers (Return = 2000)"; n
			dc.l kw_printstrvar, str0
			dc.l kw_inputint, var_n

			; main.bas 15: If n < 10 Or n > MAXN Then n = MAXN
			dc.l kw_scpltvl, var_n, 10
			dc.l kw_ftov, tmp0
			dc.l kw_scpgtvl, var_n, 2000
			dc.l kw_ftov, tmp1
			dc.l kw_orvv, tmp0, tmp1, tmp0
			dc.l kw_goto_ifzero, tmp0, if1_1
			dc.l kw_ltov, 2000, var_n
if1_1:

			; main.bas 16: Do
do2_t:

			; main.bas 17: Print
			dc.l kw_printnl

			; main.bas 18: Print "T = turbo, N = normal, X = exit"
			dc.l kw_printstrvar, str1
			dc.l kw_printnl

			; main.bas 19: Do : k = UCase$(Inkey$) : Frame : Loop Until (k = "T") Or (k = "N") Or (k = "X")
do3_t:
			dc.l kw_inkeys, stmp0
			dc.l kw_strucase, var_k, stmp0
			dc.l kw_frame
			dc.l kw_strcmpeq, var_k, str2
			dc.l kw_ftov, tmp0
			dc.l kw_strcmpeq, var_k, str3
			dc.l kw_ftov, tmp1
			dc.l kw_orvv, tmp0, tmp1, tmp0
			dc.l kw_strcmpeq, var_k, str4
			dc.l kw_ftov, tmp1
			dc.l kw_orvv, tmp0, tmp1, tmp0
			dc.l kw_goto_ifzero, tmp0, do3_t
do3_e:

			; main.bas 20: If k = "X" Then Exit Do
			dc.l kw_strcmpeq, var_k, str4
			dc.l kw_goto_iffalse, if4_1
			dc.l do2_e_go
if4_1:

			; main.bas 22: Randomize 7
			dc.l kw_seedl, 7

			; main.bas 23: For i = 0 To n
			dc.l kw_ztov, var_i
			dc.l kw_vtov, var_n, for5_l
			dc.l kw_forupv, var_i, for5_l, for5_e
for5_t:

			; main.bas 24: a(i) = Rnd(1000)
			dc.l kw_rndl, 1000, tmp1
			dc.l kw_aset, arr_a, var_i, tmp1

			; main.bas 25: Next
			dc.l kw_next1v, var_i, for5_l, for5_t
for5_e:

			; main.bas 26: Print IIf(k = "T", "Turbo", "Normal"); ": sorting "; n + 1; " numbers..."
			dc.l kw_strcmpeq, var_k, str2
			dc.l kw_ftov, tmp0
			dc.l kw_goto_ifzero, tmp0, ch6_0
			dc.l kw_strcpy, stmp0, str5
			dc.l ch6_e_go
ch6_0:
			dc.l kw_strcpy, stmp0, str6
			dc.l ch6_e_go
ch6_1:
			dc.l kw_strcpy, stmp0, str7
ch6_e:
			dc.l kw_printstrvar, stmp0
			dc.l kw_addl, var_n, 1, tmp0
			dc.l kw_printstrvar, str8
			dc.l kw_printint, tmp0
			dc.l kw_printstrvar, str9
			dc.l kw_printnl

			; main.bas 27: t0 = Ticks
			dc.l kw_ticks, tmp0
			dc.l kw_vtov, tmp0, var_t0

			; main.bas 28: If k = "T" Then
			dc.l kw_strcmpeq, var_k, str2
			dc.l kw_goto_iffalse, if7_1

			; main.bas 29: Turbo On

			; main.bas 30: ShellSort
			dc.l p_shellsort_c

			; main.bas 31: Turbo Off

			; main.bas 32: Else
			dc.l if7_e_go
if7_1:

			; main.bas 33: ShellSort
			dc.l p_shellsort_c

			; main.bas 34: End If
if7_e:

			; main.bas 35: t1 = Ticks
			dc.l kw_ticks, tmp0
			dc.l kw_vtov, tmp0, var_t1

			; main.bas 36: Print "Done - stop the stopwatch"
			dc.l kw_printstrvar, str10
			dc.l kw_printnl

			; main.bas 37: For i = 0 To 9
			dc.l kw_ztov, var_i
for8_t:

			; main.bas 38: Print a(i); " ";
			dc.l kw_aget, arr_a, var_i, tmp0
			dc.l kw_printint, tmp0
			dc.l kw_printstrvar, str11

			; main.bas 39: Next
			dc.l kw_next1l, var_i, 9, for8_t
for8_e:

			; main.bas 40: Print
			dc.l kw_printnl

			; main.bas 41: If (k = "N") And (System.TicksPerSecond > 0) Then
			dc.l kw_strcmpeq, var_k, str3
			dc.l kw_ftov, tmp0
			dc.l kw_goto_ifzero, tmp0, if9_1

			; main.bas 42: Print "took "; t1 - t0; " ticks = "; (t1 - t0) \ System.TicksPerSecond; "."; ((t1 - t0) Mod System.TicksPerSecond) * 10 \ System.TicksPerSecond; " s"
			dc.l kw_subvv, var_t1, var_t0, tmp0
			dc.l kw_printstrvar, str12
			dc.l kw_printint, tmp0
			dc.l kw_subvv, var_t1, var_t0, tmp0
			dc.l kw_divvl, tmp0, 59, tmp0
			dc.l kw_printstrvar, str13
			dc.l kw_printint, tmp0
			dc.l kw_subvv, var_t1, var_t0, tmp0
			dc.l kw_modvl, tmp0, 59, tmp0
			dc.l kw_mulvl, tmp0, 10, tmp0
			dc.l kw_divvl, tmp0, 59, tmp0
			dc.l kw_printstrvar, str14
			dc.l kw_printint, tmp0
			dc.l kw_printstrvar, str15
			dc.l kw_printnl

			; main.bas 43: ElseIf k = "T" Then
			dc.l do2_t_go
if9_1:
			dc.l kw_strcmpeq, var_k, str2
			dc.l kw_goto_iffalse, do2_t

			; main.bas 44: Print "(turbo runs with interrupts off, so"
			dc.l kw_printstrvar, str16
			dc.l kw_printnl

			; main.bas 45: Print "time it with the stopwatch)"
			dc.l kw_printstrvar, str17
			dc.l kw_printnl

			; main.bas 46: End If
if9_2:
if9_e:

			; main.bas 47: Loop
			dc.l do2_t_go
do2_e:

			; main.bas 48: End
			dc.l kw_printnl0
			dc.l kw_printstrvar, str18
			dc.l kw_waitkey
			dc.l kw_stop

; ============================================================
; sub shellsort (turbo mode)
; ============================================================

p_shellsort:

			; main.bas 51: Dim gap As Integer, i As Integer, j As Integer, t As Integer

			; main.bas 52: gap = n \ 2
			dc.l kw_divvl, var_n, 2, var_shellsort_gap

			; main.bas 53: Do While gap > 0
do10_t:
			dc.l kw_scpgtvl, var_shellsort_gap, 0
			dc.l kw_goto_iffalse, do10_e

			; main.bas 54: For i = gap To n
			dc.l kw_vtov, var_shellsort_gap, var_shellsort_i
			dc.l kw_vtov, var_n, for11_l
			dc.l kw_forupv, var_shellsort_i, for11_l, for11_e
for11_t:

			; main.bas 55: t = a(i)
			dc.l kw_aget, arr_a, var_shellsort_i, var_shellsort_t

			; main.bas 56: j = i
			dc.l kw_vtov, var_shellsort_i, var_shellsort_j

			; main.bas 57: Do While j >= gap
do12_t:
			dc.l kw_scpgevv, var_shellsort_j, var_shellsort_gap
			dc.l kw_goto_iffalse, do12_e

			; main.bas 58: If a(j - gap) <= t Then Exit Do
			dc.l kw_subvv, var_shellsort_j, var_shellsort_gap, tmp0
			dc.l kw_aget, arr_a, tmp0, tmp0
			dc.l kw_scplevv, tmp0, var_shellsort_t
			dc.l kw_goto_iffalse, if13_1
			dc.l do12_e_go
if13_1:

			; main.bas 59: a(j) = a(j - gap)
			dc.l kw_subvv, var_shellsort_j, var_shellsort_gap, tmp1
			dc.l kw_aget, arr_a, tmp1, tmp1
			dc.l kw_aset, arr_a, var_shellsort_j, tmp1

			; main.bas 60: j = j - gap
			dc.l kw_subvv, var_shellsort_j, var_shellsort_gap, var_shellsort_j

			; main.bas 61: Loop
			dc.l do12_t_go
do12_e:

			; main.bas 62: a(j) = t
			dc.l kw_aset, arr_a, var_shellsort_j, var_shellsort_t

			; main.bas 63: Next
			dc.l kw_next1v, var_shellsort_i, for11_l, for11_t
for11_e:

			; main.bas 64: gap = gap \ 2
			dc.l kw_divvl, var_shellsort_gap, 2, var_shellsort_gap

			; main.bas 65: Loop
			dc.l do10_t_go
do10_e:
			dc.l p_shellsort_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_e_go:			lea do2_e, sp
			rts
ch6_e_go:			lea ch6_e, sp
			rts
if7_e_go:			lea if7_e, sp
			rts
do2_t_go:			lea do2_t, sp
			rts
do12_e_go:			lea do12_e, sp
			rts
do12_t_go:			lea do12_t, sp
			rts
do10_t_go:			lea do10_t, sp
			rts

p_shellsort_c:		; call shellsort
			clr.w var_shellsort_gap
			clr.w var_shellsort_i
			clr.w var_shellsort_j
			clr.w var_shellsort_t
			move.l sp, p_shellsort_rs
			lea p_shellsort, sp
			rts
p_shellsort_r:		; end of shellsort
			movea.l p_shellsort_rs, sp
			rts

; ============================================================
; Variables
; ============================================================

; (68000: in the RAM block at the end, from $FF8000)

; ============================================================
; Strings
; ============================================================

str0:			dc.b "How many numbers (Return = 2000)? ", 0
str1:			dc.b "T = turbo, N = normal, X = exit", 0
str2:			dc.b "T", 0
str3:			dc.b "N", 0
str4:			dc.b "X", 0
str5:			dc.b "Turbo", 0
str6:			dc.b "Normal", 0
str7:			dc.b 0
str8:			dc.b ": sorting ", 0
str9:			dc.b " numbers...", 0
str10:			dc.b "Done - stop the stopwatch", 0
str11:			dc.b " ", 0
str12:			dc.b "took ", 0
str13:			dc.b " ticks = ", 0
str14:			dc.b ".", 0
str15:			dc.b " s", 0
str16:			dc.b "(turbo runs with interrupts off, so", 0
str17:			dc.b "time it with the stopwatch)", 0
str18:			dc.b "Press a key", 0
			even

; ============================================================
; Keyword library (used)
; ============================================================

			even
;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## ntc_d_inbuf @data

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## kw_goto_ifzero
;kw_goto_ifzero, <var>, <label>  - branch if var = 0
kw_goto_ifzero:
			movea.l (sp)+, a0
			tst.w (a0)
			beq kw_giz_go
			addq.l #4, sp
			rts
kw_giz_go:
			movea.l (sp), sp
			rts

			even
;## ntc_for_jump
; tails for the FOR / NEXT keywords: SP = thread at the label long
ntc_for_take:
			movea.l (sp), sp
			rts
ntc_for_skip:
			addq.l #4, sp
			rts

			even
;## kw_forupv ntc_for_jump
;kw_forupv, <var>, <limit var>, <endlabel>
kw_forupv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d1
			cmp.w (a0), d1
			blt ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit (past 32767: ends)
kw_next1l:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			addq.w #1, (a0)
			bvs ntc_for_skip
			cmp.w (a0), d1
			bge ntc_for_take		; limit >= var
			addq.l #4, sp
			rts

			even
;## kw_next1v ntc_for_jump
;kw_next1v, <var>, <limit var>, <toplabel>
kw_next1v:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			addq.w #1, (a0)
			bvs ntc_for_skip
			move.w (a1), d1
			cmp.w (a0), d1
			bge ntc_for_take
			addq.l #4, sp
			rts

			even
;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), (a1)
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_ftov
;kw_ftov, <destvar>  - Z flag to var: true = -1, false = 0
kw_ftov:
			seq d0
			ext.w d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

; ============================================================
; Arithmetic (16 bit, wrapping)
; ============================================================

			even
;## kw_addl
;kw_addl, <var>, <literal>, <destvar>
kw_addl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			add.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_subvv
;kw_subvv, <var1>, <var2>, <destvar>  - var1 - var2
kw_subvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			sub.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvl
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			muls.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_div
; d0.w / d1.w signed, truncating: d0.w = quotient, d1.w = remainder (the
; dividend's sign). Divide by zero: quotient 0, remainder = dividend.
; -32768 / -1: quotient -32768, remainder 0 (as the Z80 library). jmp (a6)
ntc_div:
			tst.w d1
			beq ntc_div_z
			ext.l d0
			move.l d0, d2
			divs.w d1, d0
			bvs ntc_div_ov
			move.l d0, d1
			swap d1
			jmp (a6)
ntc_div_z:
			move.w d0, d1
			moveq #0, d0
			jmp (a6)
ntc_div_ov:
			move.w #$8000, d0
			moveq #0, d1
			jmp (a6)

			even
;## kw_divvv ntc_div
;kw_divvv, <var1>, <var2>, <destvar>  - var1 \ var2
kw_divvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			lea kw_div_q, a6
			bra ntc_div
kw_div_q:
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_divvl ntc_div kw_divvv
;kw_divvl, <var>, <literal>, <destvar>
kw_divvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			lea kw_div_q, a6
			bra ntc_div

			even
;## kw_modvv ntc_div
;kw_modvv, <var1>, <var2>, <destvar>  - var1 MOD var2
kw_modvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			lea kw_mod_r, a6
			bra ntc_div
kw_mod_r:
			movea.l (sp)+, a0
			move.w d1, (a0)
			rts

			even
;## kw_modvl ntc_div kw_modvv
kw_modvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			lea kw_mod_r, a6
			bra ntc_div

			even
;## kw_orvv
kw_orvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			or.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_cmp
; tails: d0 = a, d1 = b, test a <rel> b
ntc_cmp_slt:
			cmp.w d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_cmp_sle:
			cmp.w d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_cmp_sgt:
			cmp.w d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_cmp_sge:
			cmp.w d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_cmp_ult:
			cmp.w d1, d0
			scs d0
			addq.b #1, d0
			rts
ntc_cmp_ule:
			cmp.w d1, d0
			sls d0
			addq.b #1, d0
			rts
ntc_cmp_ugt:
			cmp.w d1, d0
			shi d0
			addq.b #1, d0
			rts
ntc_cmp_uge:
			cmp.w d1, d0
			scc d0
			addq.b #1, d0
			rts
ntc_cmp_eq:
			cmp.w d1, d0
			rts
ntc_cmp_ne:
			cmp.w d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_scpltvl ntc_cmp
kw_scpltvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_slt

			even
;## kw_scplevv ntc_cmp
kw_scplevv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_sle

			even
;## kw_scpgtvl ntc_cmp
kw_scpgtvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_sgt

			even
;## kw_scpgevv ntc_cmp
kw_scpgevv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_sge

			even
;## kw_aget
;kw_aget, <arraybase>, <indexvar>, <destvar>
kw_aget:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			add.l d0, d0
			movea.l (sp)+, a1
			move.w 0(a0, d0.l), (a1)
			rts

			even
;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			add.l d0, d0
			movea.l (sp)+, a1
			move.w (a1), 0(a0, d0.l)
			rts

			even
;## ntc_rnd_seed

			even
;## kw_rndl ntc_rnd_seed ntc_div
;kw_rndl, <literal>, <destvar>
kw_rndl:
			move.l (sp)+, d1
ntc_rnd:
			move.w ntc_rnd_seed, d0		; h = high byte, l = low byte
			move.w d0, d2
			lsr.w #8, d2				; d2 = h
			moveq #0, d3
			move.b d0, d3				; d3 = l
			; h' = ((h & 1) << 7 | l >> 1) xor h
			move.b d2, d4
			andi.b #1, d4
			ror.b #1, d4
			move.b d3, d5
			lsr.b #1, d5
			or.b d5, d4
			eor.b d2, d4				; d4 = h'
			; l' = ((l & 1) << 7 | h' >> 1) xor l
			move.b d3, d5
			andi.b #1, d5
			ror.b #1, d5
			move.b d4, d6
			lsr.b #1, d6
			or.b d6, d5
			eor.b d3, d5				; d5 = l'
			eor.b d5, d4				; h'' = l' xor h'
			moveq #0, d0
			move.b d4, d0
			lsl.w #8, d0
			move.b d5, d0
			move.w d0, ntc_rnd_seed
			tst.w d1
			ble ntc_rnd_zero
			andi.w #$7FFF, d0
			lea kw_mod_rr, a6
			bra ntc_div
kw_mod_rr:
			movea.l (sp)+, a0
			move.w d1, (a0)
			rts
ntc_rnd_zero:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_seedl ntc_rnd_seed
;kw_seedl, <literal>
kw_seedl:
			move.l (sp)+, d0
			tst.w d0
			bne kw_sdl_ok
			moveq #1, d0
kw_sdl_ok:
			move.w d0, ntc_rnd_seed
			rts

; ============================================================
; Strings: 0 terminated. A string variable or temp has its capacity
; (1 .. 255 chars) in the byte before it: [cap][text...][0]. Array
; elements have no capacity byte (the caller gives the element size).
; ============================================================

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
kw_seq_lp:
			move.b (a0)+, d0
			cmp.b (a1)+, d0
			bne kw_seq_no
			tst.b d0
			bne kw_seq_lp
kw_seq_no:
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## ntc_gets ntc_data ntc_plat_screen ntc_plat_key
; line input with echo and backspace, on the real stack (jsr). a2 = buffer (its
; capacity in the byte before it). 0 terminated, then a new line.
ntc_gets:
			moveq #0, d3
			move.b -1(a2), d3			; capacity
			moveq #0, d4				; typed
ntc_gs_wait:
			jsr ntc_plat_getkey
			cmpi.b #13, d0
			beq ntc_gs_done
			cmpi.b #127, d0
			beq ntc_gs_del
			cmpi.b #8, d0
			beq ntc_gs_del
			cmpi.b #32, d0
			bcs ntc_gs_wait
			cmp.w d3, d4
			bcc ntc_gs_wait
			move.b d0, 0(a2, d4.w)
			addq.w #1, d4
			jsr ntc_plat_putc
			bra ntc_gs_wait
ntc_gs_del:
			tst.w d4
			beq ntc_gs_wait
			subq.w #1, d4
			jsr ntc_plat_backspace
			bra ntc_gs_wait
ntc_gs_done:
			clr.b 0(a2, d4.w)
			jmp ntc_plat_newline

			even
;## kw_inputint ntc_gets ntc_atoi ntc_d_inbuf
;kw_inputint, <var>  - signed decimal, stops at the first non digit
kw_inputint:
			move.l (sp)+, ntc_ivar
			lea ntc_inbuf, a2
			NTC_RS
			jsr ntc_gets
			NTC_TS
			lea ntc_inbuf, a0
			bra ntc_atoi

			even
;## ntc_atoi ntc_data
; text at a0 to a number into the var at (ntc_ivar). Spaces first, then - , then
; digits (or &H hex). Then rts (the thread).
ntc_atoi:
			moveq #0, d0				; value
			moveq #0, d2				; minus
ntc_at_sp:
			move.b (a0), d1
			cmpi.b #' ', d1
			bne ntc_at_sg
			addq.l #1, a0
			bra ntc_at_sp
ntc_at_sg:
			cmpi.b #'-', d1
			bne ntc_at_amp
			moveq #1, d2
			addq.l #1, a0
			move.b (a0), d1
ntc_at_amp:
			cmpi.b #'&', d1
			bne ntc_at_dec
			addq.l #1, a0
			move.b (a0)+, d1
			ori.b #$20, d1
			cmpi.b #'h', d1
			bne ntc_at_done
ntc_at_hex:
			moveq #0, d1
			move.b (a0)+, d1
			subi.b #'0', d1
			bcs ntc_at_done
			cmpi.b #10, d1
			bcs ntc_at_hd
			ori.b #$20, d1
			subi.b #'a'-'0', d1
			bcs ntc_at_done
			cmpi.b #6, d1
			bcc ntc_at_done
			addi.b #10, d1
ntc_at_hd:
			lsl.w #4, d0
			or.w d1, d0
			bra ntc_at_hex
ntc_at_dec:
			moveq #0, d1
			move.b (a0)+, d1
			subi.b #'0', d1
			bcs ntc_at_done
			cmpi.b #10, d1
			bcc ntc_at_done
			mulu.w #10, d0
			add.w d1, d0
			bra ntc_at_dec
ntc_at_done:
			tst.w d2
			beq ntc_at_st
			neg.w d0
ntc_at_st:
			movea.l ntc_ivar, a0
			move.w d0, (a0)
			rts

			even
;## kw_inkeys ntc_data ntc_plat_key
;kw_inkeys, <dest>  - Inkey$: the new key press as a string, "" if none
kw_inkeys:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_plat_scankey
			NTC_TS
			move.b d0, (a2)+
			beq kw_iks_e
			clr.b (a2)
kw_iks_e:
			rts

			even
;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame (vertical blank)
kw_frame:
			NTC_RS
			jsr ntc_plat_frame
			NTC_TS
			rts

			even
;## kw_ticks ntc_data ntc_plat_ticks
;kw_ticks, <destvar>  - the tick count (frames, 60 or 50 a second)
kw_ticks:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_plat_ticks
			NTC_TS
			move.w d0, (a2)
			rts

; ============================================================
; String functions. Numbers are passed as the address of a word.
; Results go to a string buffer. Dest may be the same as the source.
; ============================================================

			even
;## kw_strucase
;kw_strucase, <dest>, <src>  - UCase$
kw_strucase:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
kw_uc_lp:
			move.b (a0)+, d0
			cmpi.b #'a', d0
			bcs kw_uc_put
			cmpi.b #'z', d0
			bhi kw_uc_put
			subi.b #32, d0
kw_uc_put:
			move.b d0, (a1)+
			bne kw_uc_lp
			rts

			even
;## kw_bssinit ntc_data ntc_plat_screen
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  the RAM variables (not in the ROM). Check they fit under the end of RAM, then clear them.
;  Too big: a message, the program stops.
kw_bssinit:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			andi.l #$FFFF, d0
			move.l a0, d1
			add.l d0, d1
			cmpi.l #NTC_RAMEND, d1		; (the platform's ;@ramend, written by the compiler: $01000000 on the Mega Drive)
			bhi kw_bs_big
			tst.l d0
			beq kw_bs_e
kw_bs_lp:
			clr.b (a0)+
			subq.l #1, d0
			bne kw_bs_lp
kw_bs_e:
			rts
kw_bs_big:
			NTC_RS
			lea kw_bs_txt, a2
kw_bs_pl:
			moveq #0, d0
			move.b (a2)+, d0
			beq kw_bs_stop
			jsr ntc_plat_putc
			bra kw_bs_pl
kw_bs_stop:
			jsr ntc_plat_newline
			jmp kw_stop
kw_bs_txt:	dc.b "GURU 001", 0
			even

			even
;## ntc_ng_boot ntc_plat_data ntc_data ntc_plat_screen ntc_ng_snd
; ------------------------------------------------------------
; USER (the BIOS calls it, supervisor mode): request 0 / 1 back to the BIOS;
; 2 / 3: RAM cleared and the RAM block copied from the ROM, the screen, the
; sound driver's count; then user mode on the real stack and into ntc_start
; ------------------------------------------------------------
REG_P1CNT		equ $300000
REG_WATCHDOG	equ $300001
REG_SOUND		equ $320000
REG_P2CNT		equ $340000
REG_STATUSB		equ $380000
REG_SWPROM		equ $3A0013
REG_CRTFIX		equ $3A001B
REG_PALBANK0	equ $3A001F
REG_VRAMADDR	equ $3C0000
REG_VRAMRW		equ $3C0002
REG_VRAMMOD		equ $3C0004
REG_LSPCMODE	equ $3C0006
REG_IRQACK		equ $3C000C
NG_PALRAM		equ $400000
BIOS_SYSTEM_MODE	equ $10FD80
BIOS_USER_REQUEST	equ $10FDAE
NG_FIXMAP		equ $7000
NTC_USTACK		equ $0010E800			; the real stack's top
ntc_ng_user:
			move.b d0, REG_WATCHDOG
			move.b BIOS_USER_REQUEST, d0
			cmpi.b #2, d0
			bcc ntc_ng_game
			jmp $00C00444				; SYSTEM_RETURN
ntc_ng_rts:
			rts
ntc_ng_game:
			move.w #$2700, sr
			move.w #7, REG_IRQACK
			move.b d0, REG_WATCHDOG
			lea $00100000, a0			; RAM cleared, up to the real stack's top
			move.w #($E800/4)-1, d0
ntc_nb_clr:
			clr.l (a0)+
			dbra d0, ntc_nb_clr
			move.b d0, REG_WATCHDOG
			lea ntc_romend, a0			; the RAM block's first image, from the ROM
			lea ntc_ram, a1
			move.l #ntc_ramend-ntc_ram, d0
			beq ntc_nb_nodata
ntc_nb_cp:
			move.b (a0)+, (a1)+
			subq.l #1, d0
			bne ntc_nb_cp
ntc_nb_nodata:
			move.b d0, REG_WATCHDOG
			move.b #1, REG_CRTFIX		; the cartridge's fix tiles
			move.b d0, REG_PALBANK0
			move.w #0, REG_LSPCMODE		; no auto-animation timer
			move.w #1, REG_VRAMMOD
			move.w #$8000, REG_VRAMADDR	; every sprite full size
			move.w #$200-1, d0
ntc_nb_scb2:
			move.w #$0FFF, REG_VRAMRW
			dbra d0, ntc_nb_scb2
			move.w #$8200, REG_VRAMADDR	; and hidden (0 tall)
			move.w #$200-1, d0
ntc_nb_scb3:
			move.w #0, REG_VRAMRW
			dbra d0, ntc_nb_scb3
			move.w #$8400, REG_VRAMADDR	; x 0
			move.w #$200-1, d0
ntc_nb_scb4:
			move.w #0, REG_VRAMRW
			dbra d0, ntc_nb_scb4
			move.b d0, REG_WATCHDOG
			lea NG_PALRAM, a0			; the palettes: black; palette 0 colour 1 white
			move.w #$2000/4-1, d0
ntc_nb_pal:
			move.l #$80008000, (a0)+
			dbra d0, ntc_nb_pal
			move.w #$7FFF, NG_PALRAM+2
			move.b d0, REG_WATCHDOG
			move.b #40, ntc_scols
			move.b #28, ntc_srows
			move.b #$00, ntc_tattr
			jsr ntc_plat_cls
			move.b REG_SOUND, ntc_ngseq	; the sound driver's count so far
			move.l #NTC_USTACK, a0
			move.l a0, usp
			move.w #$0000, sr			; user mode, the interrupts on: A7 is now the user stack
			jmp ntc_start

; ------------------------------------------------------------
; interrupts (supervisor mode)
; ------------------------------------------------------------
; VBlank: until the game runs it is the BIOS's; then acknowledged, the
; watchdog kicked, counted, the pads read, the frame hook run
ntc_ng_vbl:
			btst #7, BIOS_SYSTEM_MODE
			bne ntc_nv_game
			jmp $00C00438				; SYSTEM_INT1
ntc_nv_game:
			move.w #4, REG_IRQACK
			move.b d0, REG_WATCHDOG
			movem.l d0-d4/a0-a1, -(sp)
			addq.w #1, ntc_ticks
			addq.w #1, ntc_vbl
			move.b REG_STATUSB, d2
			not.b d2
			move.b REG_P1CNT, d0
			not.b d0
			andi.w #$FF, d0
			btst #0, d2
			beq ntc_nv_s1
			bset #8, d0					; Start
ntc_nv_s1:
			btst #1, d2
			beq ntc_nv_e1
			bset #9, d0					; Select
ntc_nv_e1:
			move.w d0, ntc_pad1
			move.b REG_P2CNT, d0
			not.b d0
			andi.w #$FF, d0
			btst #2, d2
			beq ntc_nv_s2
			bset #8, d0
ntc_nv_s2:
			btst #3, d2
			beq ntc_nv_e2
			bset #9, d0
ntc_nv_e2:
			move.w d0, ntc_pad2
			move.l ntc_vhook, d0
			beq ntc_nv_nohook
			movea.l d0, a0
			jsr (a0)					; (keeps every register but d0-d4 / a0-a1)
ntc_nv_nohook:
			movem.l (sp)+, d0-d4/a0-a1
ntc_ng_rte:
			rte
ntc_ng_timer:
			move.w #2, REG_IRQACK
			rte

			even
;## ntc_ng_snd ntc_plat_data
; ntc_ng_snd - d0.b = a byte for the Z80's sound driver: sent, and its answer waited for (the
; driver answers each byte with its count of them; a dead or busy Z80 is given up on after a
; while). Real stack, keeps every register
ntc_ng_snd:
			movem.l d0-d1, -(sp)
			move.b d0, REG_SOUND
			move.b ntc_ngseq, d0
			addq.b #1, d0
			move.w #4000, d1
ntc_ns_wait:
			cmp.b REG_SOUND, d0
			beq ntc_ns_ok
			dbra d1, ntc_ns_wait
			move.b REG_SOUND, d0		; no answer: take what it says now
ntc_ns_ok:
			move.b d0, ntc_ngseq
			movem.l (sp)+, d0-d1
			rts

			even
;## ntc_plat_data

			even
;## ntc_plat_screen ntc_plat_data ntc_data ntc_ng_logs
; ntc_plat_putc - d0.b = character: in the fix layer at the cursor, move on, a
; new line after the last column. Real stack, keeps d2-d7 / a2-a6
ntc_plat_putc:
			movem.l d0-d2/a0, -(sp)
		ifd NTC_NGLOG
			bsr ntc_ng_log
		endif
			moveq #0, d1
			move.b ntc_cury, d1
			mulu.w #40, d1
			moveq #0, d2
			move.b ntc_curx, d2
			add.w d2, d1
			lea ntc_shadow, a0
			move.b d0, 0(a0, d1.w)
			bsr ntc_ng_cell			; d0 = char, the cursor's cell
			addq.b #1, ntc_curx
			move.b ntc_curx, d0
			cmp.b ntc_scols, d0
			bcs ntc_pc_nowrap
			move.b #1, ntc_wrapped
			movem.l (sp)+, d0-d2/a0
			bra ntc_nl_do
ntc_pc_nowrap:
			clr.b ntc_wrapped
			movem.l (sp)+, d0-d2/a0
			rts

; the cell at the cursor gets character d0 (the fix map: 32 cells a column, the text from row 2)
ntc_ng_cell:
			movem.l d0-d1, -(sp)
			moveq #0, d1
			move.b ntc_curx, d1
			lsl.w #5, d1
			moveq #2, d0
			add.b ntc_cury, d0
			add.w d0, d1
			addi.w #NG_FIXMAP, d1
			move.w d1, REG_VRAMADDR
			movem.l (sp)+, d0-d1
			move.l d1, -(sp)
			moveq #0, d1
			move.b ntc_tattr, d1
			lsl.w #8, d1
			move.b d0, d1
			add.w ntc_tbase, d1
			move.w d1, REG_VRAMRW
			move.l (sp)+, d1
			rts

; ntc_plat_newline - column 0, next row (scrolls at the bottom); nothing straight after a wrap
ntc_plat_newline:
		ifd NTC_NGLOG
			move.l d0, -(sp)
			moveq #10, d0
			bsr ntc_ng_log
			move.l (sp)+, d0
		endif
			tst.b ntc_wrapped
			beq ntc_nl_do
			clr.b ntc_wrapped
			rts
ntc_nl_do:
			clr.b ntc_curx
			addq.b #1, ntc_cury
			move.b ntc_cury, d0
			cmp.b ntc_srows, d0
			bcs ntc_nl_e
			subq.b #1, ntc_cury
			bra ntc_ng_scroll
ntc_nl_e:
			rts

; the text up a row: the shadow moved up, the last row cleared, the fix layer redrawn
ntc_ng_scroll:
			movem.l d0-d3/a0-a1, -(sp)
			lea ntc_shadow, a0
			lea 40(a0), a1
			move.w #40*27-1, d0
ntc_sc_mv:
			move.b (a1)+, (a0)+
			dbra d0, ntc_sc_mv
			moveq #40-1, d0
ntc_sc_cl:
			move.b #' ', (a0)+
			dbra d0, ntc_sc_cl
			bsr ntc_ng_redraw
			movem.l (sp)+, d0-d3/a0-a1
			rts

; the fix layer from the shadow (28 rows of 40): a column at a time (the fix map runs down)
ntc_ng_redraw:
			movem.l d0-d3/a0, -(sp)
			move.w #32, REG_VRAMMOD
			moveq #0, d2				; row
			moveq #0, d3
			move.b ntc_tattr, d3
			lsl.w #8, d3
ntc_rd_row:
			move.w d2, d0
			addi.w #NG_FIXMAP+2, d0
			move.w d0, REG_VRAMADDR
			lea ntc_shadow, a0
			move.w d2, d0
			mulu.w #40, d0
			adda.w d0, a0
			moveq #40-1, d1
ntc_rd_col:
			moveq #0, d0
			move.b (a0)+, d0
			bne ntc_rd_ch
			moveq #' ', d0
ntc_rd_ch:
			or.w d3, d0
			add.w ntc_tbase, d0
			move.w d0, REG_VRAMRW
			dbra d1, ntc_rd_col
			addq.w #1, d2
			cmpi.w #28, d2
			bcs ntc_rd_row
			move.w #1, REG_VRAMMOD
			movem.l (sp)+, d0-d3/a0
			rts

			even
;## ntc_plat_backspace @unit ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_backspace - back a column and clear it (not past the line's start)
ntc_plat_backspace:
			tst.b ntc_curx
			beq ntc_bs_e
			subq.b #1, ntc_curx
			move.l d0, -(sp)
			moveq #' ', d0
			bsr ntc_ng_cell
			move.l (sp)+, d0
ntc_bs_e:
			rts

			even
;## ntc_plat_cls @unit ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_cls - clear the console, the cursor home
ntc_plat_cls:
			movem.l d0/a0, -(sp)
			lea ntc_shadow, a0
			move.w #40*28-1, d0
ntc_cls_lp:
			move.b #' ', (a0)+
			dbra d0, ntc_cls_lp
			clr.b ntc_curx
			clr.b ntc_cury
			clr.b ntc_wrapped
			bsr ntc_ng_redraw
			movem.l (sp)+, d0/a0
			rts

			even
;## ntc_ng_logs
		ifd NTC_NGLOG
; test builds (vasm -DNTC_NGLOG): what the console was given, at $10C000 on (the
; harness reads it): characters, 10 for a new line. $10DFFC: where the next goes
ntc_ng_log:
			move.l a0, -(sp)
			movea.l $0010DFFC, a0
			cmpa.l #$0010C000, a0
			bcc ntc_lg_ok
			lea $0010C000, a0
ntc_lg_ok:
			cmpa.l #$0010DFF0, a0
			bcc ntc_lg_full
			move.b d0, (a0)+
			move.l a0, $0010DFFC
ntc_lg_full:
			movea.l (sp)+, a0
			rts
		endif

			even
;## ntc_plat_key ntc_data ntc_plat_data ntc_plat_frame
; ntc_plat_scankey - d0 = the code of a button newly pressed on pad 1, or 0
ntc_plat_scankey:
			movem.l d1-d2/a0, -(sp)
			move.w ntc_pad1, d1
			move.w ntc_padseen, d2
			move.w d1, ntc_padseen
			not.w d2
			and.w d2, d1				; the new ones
			moveq #0, d0
			lea ntc_ng_keys, a0
			moveq #0, d2
ntc_sk_lp:
			btst d2, d1
			bne ntc_sk_got
			addq.w #1, d2
			cmpi.w #10, d2
			bcs ntc_sk_lp
			bra ntc_sk_e
ntc_sk_got:
			move.b 0(a0, d2.w), d0
ntc_sk_e:
			movem.l (sp)+, d1-d2/a0
			rts
ntc_ng_keys:	dc.b $F0, $F1, $F2, $F3, 'A', 'B', 'C', 'D', 13, 27
			even

; ntc_plat_getkey - wait for a button: d0 = its code
ntc_plat_getkey:
			bsr ntc_plat_scankey
			tst.b d0
			bne ntc_gk_e
			bsr ntc_plat_frame
			bra ntc_plat_getkey
ntc_gk_e:
			rts

			even
;## ntc_plat_frame ntc_plat_data
; ntc_plat_frame - wait for the next VBlank interrupt
ntc_plat_frame:
			move.l d0, -(sp)
			move.w ntc_vbl, d0
ntc_fr_lp:
			cmp.w ntc_vbl, d0
			beq ntc_fr_lp
			move.l (sp)+, d0
			rts

			even
;## ntc_plat_ticks ntc_plat_data
; ntc_plat_ticks - d0.w = frames since the start (59.19 a second)
ntc_plat_ticks:
			move.w ntc_ticks, d0
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - before the program stops: nothing to give back (the watchdog is kicked by the
; VBlank interrupt, so a stopped program sits still rather than resetting)
ntc_plat_exit:
			rts


			even
ntc_romend:			; the end of the ROM: the RAM block's first image follows
			org $100000		; (;@ramorg: where this platform's variables are - 16 bit addresses, sign extended)
ntc_ram:
; variables
var_n:			dc.w 0
			dc.b 40			; capacity
var_k:			ds.b 41
			even
var_i:			dc.w 0
for5_l:			dc.w 0
var_t0:			dc.w 0
var_t1:			dc.w 0
p_shellsort_rs:			dc.l 0
var_shellsort_gap:			dc.w 0
var_shellsort_i:			dc.w 0
var_shellsort_j:			dc.w 0
var_shellsort_t:			dc.w 0
for11_l:			dc.w 0
tmp0:			dc.w 0
tmp1:			dc.w 0
			dc.b 40			; capacity
stmp0:			ds.b 41
			even
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
			dc.b 40					; ntc_inbuf's capacity (as every string variable has)
ntc_inbuf:	ds.b 41					; inputint: typed text
			even
			even
ntc_rnd_seed:	dc.w 1
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_curx:		dc.b 0				; cursor column (0 based)
ntc_cury:		dc.b 0				; cursor row (0 based)
ntc_scols:		dc.b 40				; columns
ntc_srows:		dc.b 28				; rows
ntc_wrapped:	dc.b 0				; 1 = the last character wrapped to the next line
ntc_tattr:		dc.b $00			; the text cells' palette (high 4 bits)
ntc_ngseq:		dc.b 0				; the sound driver's count of the bytes it has taken
				dc.b 0
ntc_tbase:		dc.w 0				; added to a character for its fix tile (another font)
ntc_ticks:		dc.w 0				; frames since the start
ntc_vbl:		dc.w 0				; frames (ntc_plat_frame waits for it to move)
ntc_pad1:		dc.w 0				; pad 1's buttons now (bit 0 Up ... 7 D, 8 Start, 9 Select)
ntc_pad2:		dc.w 0
ntc_padseen:	dc.w 0				; pad 1 as Inkey last saw it (new presses only)
ntc_vhook:		dc.l 0				; a routine the VBlank interrupt runs (supervisor mode), 0 none
ntc_shadow:		ds.b 40*28			; the console's text
			even
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_a		equ ntc_bss + 0		; 4002 bytes
ntc_bss_size	equ 4002
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
